/* 1er enregistrement d'un chiffrage : il garde la révision actuelle de la base */
function stampRev(ch){if(ch&&!ch.baseRev){const b=prixBase();const r=revOf(b);if(r)ch.baseRev=r;}return ch;}
const affSetCh=(a,ch)=>A.affSet(a.num,{chiffrage:stampRev(ch)});
export function prixSave(base,ctx){const now=new Date().toISOString();const who=A&&A.userName?A.userName():'';const old=regGet('prix','base');base.editedAt=now;base.editedBy=who;delete base.archived;
  if(old&&old.mo&&priceSig(old)===priceSig(base))base.rev=revOf(old); /* aucun prix ne bouge (devis relié, même classeur réimporté…) : même révision */
  else{if(old&&old.mo)archiveRev(old,ctx,now,who);base.rev=now;base.revBy=who;}
  return regSet('prix','base',base,{replace:true});}
function archiveRev(old,ctx,now,who){const r0=revOf(old);if(!r0||regGet('prix',archId(r0)))return;const canAff=!!(ctx&&ctx.canEdit);let used=false;
  regAll('affaire').forEach(a=>{const ch=a.chiffrage||{};if(ch.baseRev===r0||(a.chiffrages||[]).some(v=>v&&v.chiffrage&&v.chiffrage.baseRev===r0)){used=true;return;}
    if(!ch.baseRev&&canAff&&(ch.etudes||[]).length&&(a.id||a.num)){regSet('affaire',a.id||a.num,{chiffrage:Object.assign({},ch,{baseRev:r0})},{quiet:true});used=true;}}); /* dossier ancien : rattaché à la révision qu'il utilisait */
  if(!used&&regLoaded('affaire'))return; /* révision qui ne sert à aucun dossier : pas d'archive (affaires pas encore chargées : on archive, par prudence) */
  const o=ensureSM(Object.assign({},old));delete o.id;o.rev=r0;regSet('prix',archId(r0),{rev:r0,version:old.version||'',at:old.at||'',archived:{at:now,by:who},z:packBase(o)},{replace:true,quiet:true});}
