/* points techniques : anciennes saisies remises au modèle du 13/10 (CND feeder / antennes, tronçons d'essai avec leurs prestations) — sans rien perdre */
export function migratePoints(pt0){const pt=clone(pt0||{});
  ['radio','us','ress'].forEach(k=>{const c=pt[k];if(!c||typeof c!=='object')return;if(c.pct!==undefined&&c.fdPct===undefined&&c.antPct===undefined){c.fdPct=c.pctFd!==undefined?c.pctFd:c.pct;c.antPct=c.pct;}if(c.vac!==undefined&&c.fdVac===undefined&&c.antVac===undefined){c.fdVac=c.vac;c.antVac=c.vac;}delete c.pct;delete c.pctFd;delete c.vac;});
  const H=pt.hydro=pt.hydro&&typeof pt.hydro==='object'?pt.hydro:{};const G={};['eau','rincage','passivation','conservation'].forEach(k=>{if(pt[k]&&typeof pt[k]==='object'){G[k]=!!pt[k].on;delete pt[k];}});
  if(!Array.isArray(H.troncons)){const old=Array.isArray(H.rows)?H.rows:[];const by=[];old.forEach((r,i)=>{const nom=String(r.nom||'').trim()||('Tronçon '+(i+1));let t=by.find(x=>x.nom===nom);if(!t){t={id:'T'+(by.length+1),nom,rows:[],epreuve:true};by.push(t);}t.rows.push({dn:r.dn,ml:r.ml});});H.troncons=by;delete H.rows;}
  if(Object.keys(G).length)H.troncons.forEach(t=>{Object.keys(G).forEach(k=>{if(t[k]===undefined)t[k]=G[k];});});
  H.troncons.forEach((t,i)=>{if(!t.id)t.id='T'+(i+1)+Math.random().toString(36).slice(2,5);if(!Array.isArray(t.rows))t.rows=[];});
  return pt;}
