/* ═════════ 4 bis · DÉTAIL D'UNE PRESTATION CALCULÉE (13/10 soir, Ethan : « une extrusion, comme les épreuves, ça doit être comme vidange : voir le calcul décomposé
   du panier et travailler dessus, changer des quantités… la dépose, toutes les prestations ») — lignes rendues par le moteur (prix.js lineSet) ; quantité et PU
   modifiables pour CE chiffrage : zone → z.pover[clé], onglet Épreuves → chiffrage.essais.pover[clé] ═════════ */
const detIdx=(det,i)=>((det||{}).rows||[]).find(x=>x.idx===i)||null;
const PRH=[['epreuve','Épreuve hydraulique'],['eau','Eau adoucie'],['rincage','Rinçage'],['passivation','Passivation'],['conservation','Conservation']];
const HYLAB={epreuve:'Épreuve hydraulique',eau:'Remplissage en eau adoucie',rincage:'Rinçage dynamique',passivation:'Passivation',conservation:'Mise en conservation'};
const epName=(zz,i)=>{const n=String((zz||{}).nom||'').trim();return !n||/^zone\s*\d*$/i.test(n)?'Épreuve '+(i+1):n;}; /* 13/10 soir : « zone » réservé aux zones du chiffrage */
function pvDetHTML(scope,key,lines,ro,opts){opts=opts||{};if(!lines||!lines.length)return '';const ck='pv|'+scope+'|'+key;const open=!!CS.pdet[ck];const sum=k=>lines.reduce((x,l)=>x+(!k||l.kind===k?l.amount:0),0);const mod=lines.some(l=>l.mod);const ek=encodeURIComponent(key);
  const head=`<button class="ch-pdsum" data-act="af" data-v="chpv|${scope}|${ek}" title="Le détail du calcul : quantités et prix modifiables pour ce chiffrage">${open?'▾':'▸'} ${esc(opts.title||'Détail du calcul')} · MO ${eur(sum('mo'))} · fournitures ${eur(sum('fo'))}${sum('st')?' · sous-traitance '+eur(sum('st')):''} = <b>${eur(sum())}</b>${opts.unit?' '+esc(opts.unit):''}${mod?' <span class="eq-tag warn" title="Quantités ou prix changés dans ce chiffrage">⚠ modifié</span>':''}</button>`;
  if(!open)return `<div class="ch-pdet">${head}</div>`;const pre=scope==='es'?'espov§':'pov§';
  const inp=(l,f)=>{const set=!!(l.ov&&l.ov[f]);const bv=l.base[f];return `<input class="f ch-in ch-n${set?' ch-ov':''}" type="number" step="any" min="0" data-afx="${pre}${esc(key)}§${esc(l.id)}§${f}" value="${set?esc(f==='qty'?l.qty:l.pu):''}" placeholder="${n2(bv)}" ${ro?'disabled':''}>${set?`<small class="ch-base" title="Valeur de la base de prix">base ${nb(bv,2)}</small>`:''}`;};
  const rows=lines.map(l=>`<tr><td>${esc(l.label)}${l.kind==='st'?' <small class="dim">· sous-traitance</small>':''}</td><td><span class="ch-pair">${inp(l,'qty')}<small>${esc(l.unit||'')}</small></span></td><td><span class="ch-pair">${inp(l,'pu')}<small>€</small></span></td><td class="num"><b>${nb(l.amount,2)}</b></td><td>${l.mod&&!ro?`<button class="lnk" data-act="af" data-v="chpvz|${scope}|${ek}|${esc(l.id)}" title="Revenir à la base">↺</button>`:''}</td></tr>`).join('');
  return `<div class="ch-pdet open">${head}<div style="overflow:auto"><table class="rc af-tab ch-tab ch-pdt"><tr><th>Ligne</th><th>Qté · heures</th><th>PU · taux</th><th>Montant</th><th></th></tr>${rows}<tr class="tot"><td>Total${opts.unit?' '+esc(opts.unit):''}</td><td></td><td></td><td class="num"><b>${nb(sum(),2)}</b></td><td></td></tr></table></div><div class="hint">Une valeur saisie ici ne vaut que pour CE chiffrage (la base de prix ne bouge pas) ; vide = la base (en gris).${opts.hint?' '+esc(opts.hint):''}</div></div>`;}
/* une prestation hydraulique : sur combien d'épreuves, une par épreuve ou GLOBALE, le PRIX RETENU (calcul SCR ou devis), le détail de chaque calcul */
function prixLine(o){const {k,label,items,n,N,glob,calc,ro}=o;const devV=num(o.devisV);const mode=o.mode||(devV>0?'devis':'calc');const pf=o.pfx;
  const gsel=k==='epreuve'?'':SEL(pf+'global.'+k,glob?1:'',[['','une par épreuve'],[1,'GLOBALE : une seule fois']],ro,'ch-glob');
  return `<div class="ch-cnd ch-prl${n?'':' off'}"><div class="ch-cnd-h"><b>${esc(label)}</b><small class="dim">${n} / ${N} épreuve${N>1?'s':''}</small>${gsel}<span class="ch-prix"><small>prix retenu</small>${SEL(pf+'prixMode.'+k,mode,[['calc','calcul SCR · '+eur(calc)],['devis','devis sous-traitant']],ro,'ch-pmode')}${mode==='devis'?IN(pf+'devis.'+k,o.devisV,{ro,cls:'ch-n',ph:'€ du devis',w:'110px'}):''}</span><span class="ch-tot${o.tot?'':' zero'}">${eur(o.tot)}</span></div>
    ${mode==='devis'&&!o.useDev&&n?`<div class="ch-sub">Devis choisi mais sans montant : le calcul SCR (${eur(calc)}) reste retenu tant que le montant est vide.</div>`:''}${mode==='devis'&&o.useDev?`<div class="ch-sub">Retenu : le devis (${eur(devV)}) — le calcul SCR donnerait ${eur(calc)}.</div>`:''}
    ${glob&&items.length?`<div class="ch-sub">Globale : ${nb(items[0].V,2)} m³ sur ${items[0].keys.length} épreuve${items[0].keys.length>1?'s':''} — frais fixes et trajet comptés une fois.</div>`:''}
    ${k==='epreuve'?'':items.map(it=>pvDetHTML(o.scope,it.key,it.lines,ro,{title:label+' · '+(it.keys.length>1?'globale':o.nameOf(it.keys[0]))+' · détail du calcul'})).join('')}</div>`;}
