  const locTab=locOn.length?`<div class="ch-loc"><div class="eq-lab">Location base vie · ${C.d0&&C.d1?`<b>${nbJ} jours ouvrés</b> (lundi → vendredi, du ${dFR(C.d0)} au ${dFR(C.d1)} · ${JC.cal} j calendaires)${fer.length?` · <span style="color:#7a5200">férié${fer.length>1?'s':''} dans la période : ${fer.join(', ')} (non déduit${fer.length>1?'s':''})</span>`:''}`:'renseigne les dates du chantier'}</div><div style="overflow:auto"><table class="rc af-tab ch-tab"><tr><th>Élément</th><th>Jours retenus</th><th>État</th><th>Prix / jour</th><th>Location</th></tr>${locOn.map(locRow).join('')}</table></div></div>`:'';
  /* ── chantier ── */
  const instBan=instOn?`<div class="ch-instban">🏗 Locations, pelle, amené / repli, déchargements, transfert, DOE / carnet : comptés dans l'onglet <button class="lnk" data-act="af" data-v="chview|inst">Installations</button> — part ventilée sur cette zone : <b>${eur(instPart)}</b> (${esc(({ml:'au ml',prix:'au prix',mo:'aux jours d\'équipe',egal:'à parts égales',pct:'en %'})[((a.chiffrage||{}).inst||{}).ventil||'ml'])}).</div>`:'';
  const chantier=card('chantier','Chantier et période',`${nbJ?nbJ+' jours ouvrés':'dates du chantier'} · ${T.ml?nb(T.ml)+' ml':'linéaire'}${instOn?' · installations : onglet commun':''}`,`<div class="ch-grid">${FLD('Nom de la zone / du lot',IN(p+'nom',z.nom,{type:'text',ro}))}${FLD('Ce que couvre la zone',IN(p+'desc',z.desc,{type:'text',ro,ph:'ex. antenne rue des Lilas · DPGF onglet 2'}),'260px')}${FLD('Début',IN(p+'chantier.d0',C.d0,{type:'date',ro}))}${FLD('Fin',IN(p+'chantier.d1',C.d1,{type:'date',ro}))}${FLD('Type de chantier',SEL(p+'chantier.type',C.type||'Gros',[['Gros','Gros chantier'],['Petit','Petit chantier']],ro))}${FLD('Isolation',SEL(p+'chantier.iso',C.iso||'Iso 1',ISOS,ro))}${FLD('ml saisis =',SEL(p+'mlMode',z.mlMode||'tranchee',[['tranchee','ml de tranchée (×2 tubes)'],['tube','ml de tube (aller + retour)']],ro))}</div>
    ${instOn?`${instBan}<div class="ch-sws">${SW(p+'chantier.bardage','Déduction bardage',C.bardage,ro)}</div>`:`<div class="ch-sws">${SW(p+'chantier.wc','WC',C.wc,ro)}${SW(p+'chantier.contener','Conteneur',C.contener,ro)}${SW(p+'chantier.benne','Benne (+ déchets)',C.benne,ro)}${SW(p+'chantier.pelle','Location pelle',C.pelle,ro)}${SW(p+'chantier.arMO','Amené / repli équipe',C.arMO,ro)}${SW(p+'chantier.transfert','Transfert',C.transfert,ro)}${SW(p+'chantier.bardage','Déduction bardage',C.bardage,ro)}${SW(p+'chantier.doe','DOE',C.doe,ro)}${SW(p+'chantier.carnet','Carnet de soudure',C.carnet,ro)}</div>`}
    <div class="ch-grid">${instOn?'':`${C.pelle?FLD('A/R pelle (nb)',IN(p+'chantier.arPelle',C.arPelle,{ro})):''}${C.arMO?FLD('Amené / repli (nb)',IN(p+'chantier.arMOQty',C.arMOQty,{ro})):''}${FLD('Déchargements (nb)',IN(p+'chantier.nbDecharg',C.nbDecharg,{ro}))}`}${C.bardage?FLD('Bardage €/ml déduit',IN(p+'chantier.tauxBardage',C.tauxBardage,{ro})):''}${C.transfert&&!instOn?FLD('Transfert : équipe 1',SEL(p+'chantier.eq1',C.eq1||'S+T+P',eqOpts(base),ro))+FLD('équipe 2',SEL(p+'chantier.eq2',C.eq2||'M',eqOpts(base),ro))+FLD('heures / opération',IN(p+'chantier.hTransfert',C.hTransfert,{ro}))+FLD('opérations',IN(p+'chantier.nbOper',C.nbOper,{ro}))+FLD('',SW(p+'chantier.camionPlateau','Camion plateau',C.camionPlateau,ro)+SW(p+'chantier.grue','Petite grue',C.grue,ro))+(C.grue?FLD('heures de grue',IN(p+'chantier.hGrue',C.hGrue,{ro})):''):''}</div>
    ${instOn?'':locTab}<div class="ch-sub">${instOn?'Dans cette zone : bardage '+eur((R.postes.bardage||{}).achat)+(R.postes.doe&&R.postes.doe.achat?' · plan iso '+eur(R.postes.doe.achat):''):''}${instOn?'</div><div hidden>':''}Amené-repli ${eur((R.postes.amene||{}).achat)} · conteneur / benne / pelle / WC ${eur((R.postes.conteneur||{}).achat)}${d.conteneur&&d.conteneur.fJour?' (location '+BASE_VIE.filter(([k])=>C[k]).map(([k,lab])=>lab.replace(/ \(.*\)/,'')+' '+((d.conteneur.jours||{})[k]||0)+' j').join(', ')+(d.conteneur.rot?' · '+d.conteneur.rot+' rotations':'')+(d.conteneur.dechets?' · déchets '+eur(d.conteneur.dechets):'')+')':''} · déchargement ${eur((R.postes.decharg||{}).achat)} · transfert ${eur((R.postes.transfert||{}).achat)} · bardage ${eur((R.postes.bardage||{}).achat)} · DOE / carnet ${eur((R.postes.doe||{}).achat)}</div>`,{total:totOf(R,['amene','conteneur','decharg','transfert','bardage','doe'])});
  /* ── équipes et cadences ── */
  const cS=d.dn?d.dn.cS:teamCost(base,E.soud),cM=d.dn?d.dn.cM:teamCost(base,E.manch);const dnD=d.dn||{};const isSM=(E.soud||'S+T+P')===SM; /* 14/10 après-midi (lot A) : équipe S+M — l'équipe manchon est comprise */
