  const fpRows=(FP.rows||[]).map((r,i)=>`<tr><td>${SEL(p+'fopre.rows.'+i+'.dn',r.dn,dnOpts(base),ro,'ch-dn')}</td>${fpK.map(([k])=>`<td><div class="ch-pair">${IN(p+'fopre.rows.'+i+'.'+k+'.q',(r[k]||{}).q,{ro,cls:'ch-n',ph:'qté'})}${IN(p+'fopre.rows.'+i+'.'+k+'.pu',(r[k]||{}).pu,{ro,cls:'ch-n',ph:'PU'})}</div></td>`).join('')}<td class="num"><b>${nb(fpK.reduce((s,[k])=>s+num((r[k]||{}).q)*num((r[k]||{}).pu),0))}</b></td><td>${rmBtn('chrm|fopre.rows|'+i,ro)}</td></tr>`).join('');
  const fopre=card('fopre','Fourniture préisolée',(R.postes.fo_preiso||{}).achat?eur((R.postes.fo_preiso||{}).achat):'non chiffrée (fournie par le client ?)',`<div style="overflow:auto"><table class="rc af-tab ch-tab"><tr><th>DN</th>${fpK.map(([k,l])=>`<th>${l}<br><small>qté · PU</small></th>`).join('')}<th>Total</th><th></th></tr>${fpRows}</table></div><div class="eq-acts" style="margin-top:6px">${addBtn('chadd|fopre.rows','DN',ro)}</div><div class="ch-grid"><div class="ch-f"><label class="f">Ou devis fournisseur (€, remplace le détail)</label>${IN(p+'fopre.prixFO',FP.prixFO,{ro})}</div><div class="ch-f"><label class="f">Transport (€)</label>${IN(p+'fopre.prixTransport',FP.prixTransport,{ro})}</div></div>`,{total:(R.postes.fo_preiso||{}).achat,foldDefault:!(FP.rows||[]).length&&!num(FP.prixFO)});
