export async function prixImportFile(file,ctx){const say=t=>A.toast&&A.toast(t);say('Lecture du classeur…');
  try{const base=await parsePrixWorkbook(file,{name:file.name});delete base.op.blocks; /* le dump brut des blocs ne sert qu'à l'analyse : pas en base */
    const old=prixBase();if(old&&old.over)base.over=old.over;if(old&&old.devis)base.devis=old.devis;if(old&&old.foDevis)base.foDevis=old.foDevis; /* 13/10 soir : les devis de référence survivent au réimport */
    /* 14/10 après-midi (lot A) : ce que le classeur n'a pas survit aussi au réimport — variantes d'équipe, équipe S+M (sa composition) et ses cadences par DN,
       paramètres de l'appli saisis (avant : perdus au réimport) */
    if(old){if(old.mvar)base.mvar=old.mvar;const oSM=(old.mo.equipes||[]).find(e=>e&&e.code===SM);if(oSM){base.mo.equipes=(base.mo.equipes||[]).filter(e=>e.code!==SM||!e.app).concat((base.mo.equipes||[]).some(e=>e.code===SM&&!e.app)?[]:[clone(oSM)]);}
      (base.mo.cad||[]).forEach(c=>{const o=(old.mo.cad||[]).find(x=>x.dn===c.dn);if(!o)return;if(num((o.soud||{})[SM])>0&&!(num((c.soud||{})[SM])>0))c.soud[SM]=o.soud[SM];if(num(o.manchSM)>0&&!(num(c.manchSM)>0))c.manchSM=o.manchSM;});
      APP_PARAMS.forEach(([k])=>{const v=(old.fo.params||{})[k];if(v!==undefined&&v!==null&&v!==''&&base.fo.params[k]===undefined)base.fo.params[k]=v;});}base.importedAt=new Date().toISOString();base.importedBy=A.userName?A.userName():'';
    if(old&&!confirm('Remplacer la base de prix actuelle ('+(old.version||'?')+(old.at?' du '+dFR(old.at):'')+') par ce classeur ('+(base.version||'?')+(base.at?' du '+dFR(base.at):'')+') ?'))return;
    prixSave(base,ctx);CS.view='base';CS.baseTab='import';say('Base de prix importée : '+(base.version||'')+' · '+(base.mo.cad||[]).length+' DN · '+(base.op.paniers||[]).length+' paniers · '+Object.keys(base.fo.params).length+' paramètres');if(ctx.render)ctx.render();}
  catch(e){console.warn(e);say('Classeur illisible : '+(e.message||e));}}
